key.query:
query GetHomeBanners {
  page(id: "home", idType: URI) {
    homePageBanners {
      homeBanners {
        bannerImage {
          node {
            mediaItemUrl
            sourceUrl
            __typename
          }
          __typename
        }
        bannerTitle
        bannerSubtitle
        bannerHref
        __typename
      }
      __typename
    }
    __typename
  }
}
